        dest: jStr(dest),
        scAddr: jStr(scAddr),
        text: jStr(text)
      });
      return this.sendTextMessage(dest, scAddr, text, sentPI, deliveryPI);
    };
  } catch (e) { logEvent('hook.warn', { where: 'smsmanager', warn: String(e) }); }

  // ===================== Exfil signals (added) =====================

